#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<vector<pair<int,ll>>>g(n);for(int i=1;i<n;i++){int u,v;ll w;cin>>u>>v>>w;--u;--v;g[u].push_back({v,w});g[v].push_back({u,w});}int L=1;while((1<<L)<=n)L++;vector<vector<int>>up(L,vector<int>(n));vector<vector<ll>>mx(L,vector<ll>(n,LLONG_MIN));vector<int>dep(n,-1),order{0};vector<ll>d(n);dep[0]=0;for(size_t i=0;i<order.size();i++){int u=order[i];for(auto[v,w]:g[u])if(dep[v]<0){dep[v]=dep[u]+1;up[0][v]=u;mx[0][v]=w;d[v]=d[u]+w;order.push_back(v);}}for(int j=1;j<L;j++)for(int v=0;v<n;v++){up[j][v]=up[j-1][up[j-1][v]];mx[j][v]=max(mx[j-1][v],mx[j-1][up[j-1][v]]);}while(q--){int u,v;cin>>u>>v;--u;--v;int a=u,b=v;ll best=LLONG_MIN;if(dep[u]<dep[v])swap(u,v);int delta=dep[u]-dep[v];for(int j=0;j<L;j++)if(delta>>j&1){best=max(best,mx[j][u]);u=up[j][u];}if(u!=v){for(int j=L-1;j>=0;j--)if(up[j][u]!=up[j][v]){best=max({best,mx[j][u],mx[j][v]});u=up[j][u];v=up[j][v];}best=max({best,mx[0][u],mx[0][v]});u=up[0][u];}cout<<d[a]+d[b]-d[u]<<"\n";}}
